<section class="card"><div class="card-heading"><div><span class="section-kicker">DIRETÓRIO CENTRAL</span><h2>Usuários dos produtos</h2></div><span class="badge"><?= count($users) ?> usuário(s)</span></div><form method="get" action="/usuarios-sistemas" class="filter-row"><label>Plataforma <select name="system_id"><option value="0">Todas as plataformas</option><?php foreach ($systems as $system): ?><option value="<?= e($system['id']) ?>" <?= $systemFilter === (int) $system['id'] ? 'selected' : '' ?>><?= e($system['name']) ?></option><?php endforeach; ?></select></label><button>Filtrar</button></form><p class="muted">Dados sincronizados dos produtos. “Último acesso” passa a ser registrado no Checklist a cada novo login.</p></section>
<section class="card users-list"><div class="table-wrap"><table><thead><tr><th>Plataforma</th><th>Empresa</th><th>Usuário</th><th>Inclusão</th><th>Último acesso</th><th>Indicações</th><th>Papel</th><th>Status</th></tr></thead><tbody><?php foreach ($users as $user): ?><tr><td><?= e($user['system_name']) ?></td><td><?= e($user['tenant_name'] ?: '—') ?></td><td><strong><?= e($user['name']) ?></strong><br><span class="muted"><?= e($user['email']) ?></span></td><td><?= e($user['registered_at'] ?: $user['created_at']) ?></td><td><?= e($user['last_seen_at'] ?: 'Ainda não registrado') ?></td><td><?= (int) ($user['referral_count'] ?? 0) ?></td><td><?= e($user['role'] ?: '—') ?></td><td><form method="post" action="/usuarios-sistemas/atualizar" class="status-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($user['id']) ?>"><select name="status"><?php foreach (['active','invited','suspended','inactive'] as $value): ?><option <?= $user['status'] === $value ? 'selected' : '' ?>><?= $value ?></option><?php endforeach; ?></select><button>Alterar</button></form></td></tr><?php endforeach; ?><?php if (!$users): ?><tr><td colspan="8" class="empty-state">Nenhum usuário encontrado para esta plataforma.</td></tr><?php endif; ?></tbody></table></div></section>
